// Title: Compute SHA256 checksum of a TIFF image generated by Aspose.Cells in C#
// Common Searches: C# code to calculate SHA256 hash of a TIFF file exported from Aspose.Cells | verify integrity of TIFF output after saving workbook with Aspose.Cells | how to generate file checksum for Aspose.Cells TIFF export using System.Security.Cryptography | example of reading a saved TIFF and computing its SHA256 hash in .NET
// Tags: SHA256 hash generation for TIFF images using Aspose.Cells | Aspose.Cells workbook export to TIFF with checksum verification | C# file integrity check after image export | System.Security.Cryptography compute file hash .NET | validate TIFF output integrity in C# applications

using System;
using System.IO;
using System.Security.Cryptography;
using Aspose.Cells;

// Creates a workbook, adds data, saves it as a TIFF image with Aspose.Cells, then reads the saved file, computes its SHA256 hash using System.Security.Cryptography, and prints the checksum for integrity verification.
class Program
{
    static void Main()
    {
        // Create a new workbook with a single worksheet
        Workbook workbook = new Workbook();
        Worksheet sheet = workbook.Worksheets[0];
        sheet.Cells["A1"].PutValue("Hello, Aspose.Cells!");
        sheet.Cells["A2"].PutValue(12345);

        // Define the output TIFF file path
        string tiffPath = "output.tiff";

        // Save the workbook as a TIFF image
        workbook.Save(tiffPath, SaveFormat.Tiff);

        // Compute SHA256 checksum of the saved TIFF file
        byte[] fileBytes = File.ReadAllBytes(tiffPath);
        string checksum;
        using (SHA256 sha256 = SHA256.Create())
        {
            byte[] hash = sha256.ComputeHash(fileBytes);
            checksum = BitConverter.ToString(hash).Replace("-", "").ToLowerInvariant();
        }

        // Output the checksum for verification
        Console.WriteLine($"SHA256 checksum of '{tiffPath}': {checksum}");
    }
}
